from typing import List
from wordle.types import Feedback


def score_guess(guess: str, target: str) -> List[Feedback]:
    """Score a guess against the target word with proper duplicate handling."""
    feedback = [Feedback.MISS] * 5  # Initialize with all misses

    # Count occurrences of each letter in both words
    guess_counts = _count_letters(guess)
    target_counts = _count_letters(target)

    # Mark exact matches (HIT)
    _mark_hits(guess, target, feedback)

    # Count remaining occurrences of each letter in target
    remaining_target_counts = {letter: count for letter, count in target_counts.items()}
    for i, letter in enumerate(guess):
        if feedback[i] == Feedback.HIT:
            remaining_target_counts[letter] -= 1

    # Mark letters present in wrong positions (PRESENT)
    _mark_presents(guess, target, feedback, remaining_target_counts)

    return feedback


def _count_letters(word: str) -> dict[str, int]:
    """Count occurrences of each letter in a word."""
    counts = {}
    for letter in word:
        if letter in counts:
            counts[letter] += 1
        else:
            counts[letter] = 1
    return counts


def _mark_hits(guess: str, target: str, feedback: List[Feedback]) -> None:
    """Mark exact matches (HIT) in the feedback list."""
    for i, (guess_letter, target_letter) in enumerate(zip(guess, target)):
        if guess_letter == target_letter:
            feedback[i] = Feedback.HIT


def _mark_presents(guess: str, target: str, feedback: List[Feedback], remaining_target_counts: dict[str, int]) -> None:
    """Mark letters present in wrong positions (PRESENT) in the feedback list."""
    for i, guess_letter in enumerate(guess):
        if feedback[i] == Feedback.MISS and guess_letter in remaining_target_counts and remaining_target_counts[guess_letter] > 0:
            feedback[i] = Feedback.PRESENT
            remaining_target_counts[guess_letter] -= 1

